static enum MHD_Result get_user(void *cls, struct MHD_Connection *c,
    const char *url, const char *method, const char *version,
    const char *upload_data, size_t *upload_data_size, void **con_cls) {
    (void) cls; (void) method; (void) version; (void) con_cls;
    if (*upload_data_size != 0) { *upload_data_size = 0; return MHD_YES; }
    long id = strtol(url + 7, NULL, 10);
    struct user_view u;                        /* domain result */
    if (domain_user_find(id, &u) != DOMAIN_OK) {
        return respond_not_found(c);           /* responder */
    }
    return respond_json_user(c, &u);           /* responder */
}
